#define R iResolution.xy
#define palOffset 5.0 

vec2 rand(vec2 p){
    p.yx+=sin(p+vec2(0.,1.));
    p.yx+=sin(p+vec2(0.,1.));
    return fract(sin(23.67+p*97.24)*54.91)*2.-1.;
}

vec2 noise(vec2 p){
    vec2 i_p = floor(p),
         f_p = smoothstep(0.,1.,fract(p));
    return mix(mix(
        rand(i_p),rand(i_p+vec2(1.,0.)),f_p.x),mix(
        rand(i_p+vec2(0.,1.)),rand(i_p+vec2(1.)),f_p.x
    ),f_p.y);
}
//https://iquilezles.org/articles/distfunctions2d/
float sdSegment( in vec2 p, in vec2 a, in vec2 b )
{
    vec2 pa = p-a, ba = b-a;
    float h = clamp( dot(pa,ba)/dot(ba,ba), 0.0, 1.0 );
    return length( pa - ba*h );
}
vec3 pal(float n){
    return cos(n+vec3(0.,5.,9.)+palOffset)*.5+.5;
}
vec3 scene(vec2 p){
    vec2 i_p = floor(p*2.),
         f_p = fract(p*2.)*2.-1.;
    float val=0.;
    for(int i=-1; i<=1; i++){
        for(int j=-1; j<=1; j++){
            vec2 off = vec2(float(i),float(j));
            vec2 a = rand((i_p+off)*999.9),
                 b = rand(a*999.9);
            if(sdSegment(f_p-off*2.,a,b)<.2){
                val = 1.;
            }
        }
    }
    for(int i=-1; i<=1; i++){
        for(int j=-1; j<=1; j++){
            vec2 off = vec2(float(i),float(j));
            vec2 ballp = rand((i_p+vec2(9.9)+off)*999.9);
            vec2 ballr = rand(ballp*999.9);
            if(length(f_p-off*2.-ballp)<max(ballr.x*.5+.5,.2)){
                val = 2.;
            }
        }
    }

    return pal(val);
}

vec2 busSeat(vec2 p){
    const float div = 16.0;
    vec2 i_p = floor(p*div),
         f_p = fract(p*div);
    vec2 q = p+noise(p*div)*.09;
    vec2 i_q = floor(q*div);
    i_p += rand(i_q)*div*.015;
    return (i_p+f_p)/div;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = 2.*(fragCoord-R*.5)/R.y;

    uv.x -= iTime;

    fragColor = vec4(scene(busSeat(uv)),1.0);
}
